\bigcap A & = \Setabs{x}{x \text{ అనేది } A\text{లోని ప్రతి మూలకానికి చెందుతుంది}},
\text{ అంటే,}\\
 & = \Setabs{x}{\text{ప్రతి } B \in A\text{ కోసం}, x \in B}

